<?php session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../db.php'; require_once __DIR__ . '/../includes/helpers.php'; require_admin_auth(); $rows=db()->query('SELECT c.*,cl.name AS client_name FROM chatbot_conversations c JOIN chatbot_clients cl ON cl.id=c.client_id ORDER BY c.updated_at DESC LIMIT 200')->fetchAll(); ?><!doctype html><html><body><h1>Conversations</h1><table border='1'><tr><th>Client</th><th>ID</th><th>Lead</th><th>Updated</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['client_name'])?></td><td><?=e($r['id'])?></td><td><?=e($r['lead_status'])?></td><td><?=e($r['updated_at'])?></td><td><a href='conversation-view.php?id=<?=e($r['id'])?>'>View</a></td></tr><?php endforeach;?></table></body></html>
